import{_ as t}from"./chunks/ip-confirm.DKirZ_6E.js";import{_ as o}from"./chunks/options-network.BC245pY_.js";import{_ as a,o as s,c as n,a2 as r}from"./chunks/framework.CfwCq2QB.js";const y=JSON.parse('{"title":"Real IP protection","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/ip-protection.md","filePath":"en/features/ip-protection.md"}'),i={name:"en/features/ip-protection.md"};function l(c,e,d,h,p,u){return s(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="real-ip-protection" tabindex="-1">Real IP protection <a class="header-anchor" href="#real-ip-protection" aria-label="Permalink to &quot;Real IP protection&quot;">​</a></h1><p>In one line: with a proxy on, sites can still use WebRTC to bypass it and grab your real IP — and from it guess your city and carrier. With protection on, sites only see the proxy&#39;s IP.</p><h2 id="what-it-covers-—-and-what-it-doesn-t" tabindex="-1">What it covers — and what it doesn&#39;t <a class="header-anchor" href="#what-it-covers-—-and-what-it-doesn-t" aria-label="Permalink to &quot;What it covers — and what it doesn&#39;t&quot;">​</a></h2><ul><li><strong>Covers</strong>: web pages using WebRTC (the tech behind in-page audio/video calls) to slip past your proxy and probe your real IP and LAN addresses</li><li><strong>Doesn&#39;t cover</strong>: other apps on your computer (they don&#39;t go through the browser); precise location permission requests — the browser prompts for those separately</li></ul><p>If you browse through a proxy, turn protection on. Without a proxy you usually don&#39;t need it.</p><h2 id="protection-levels" tabindex="-1">Protection levels <a class="header-anchor" href="#protection-levels" aria-label="Permalink to &quot;Protection levels&quot;">​</a></h2><p>Under Settings → Network → Real IP protection:</p><table tabindex="0"><thead><tr><th>Level</th><th>Effect</th><th>Cost</th></tr></thead><tbody><tr><td>Off (browser default)</td><td>Pages can quietly get your real IP and LAN addresses</td><td>None</td></tr><tr><td>Hide VPN / virtual adapters</td><td>Stops exposing extra adapters like VPNs and VMs</td><td>Minimal: calls that only connect via VPN / virtual adapters may fail</td></tr><tr><td>Hide LAN addresses</td><td>Pages can&#39;t see home / office network addresses</td><td>Small: same-LAN calls and P2P reroute through the internet, possibly slower</td></tr><tr><td><strong>Hide real IP (recommended)</strong></td><td>With a proxy on, pages only see the proxy&#39;s IP</td><td>A few in-page video calls may slow down or fail</td></tr></tbody></table><p>These settings save immediately — no need to click &quot;Save and apply&quot; above.</p><h2 id="the-confirmation-dialog-what-changes-what-s-affected" tabindex="-1">The confirmation dialog: what changes, what&#39;s affected <a class="header-anchor" href="#the-confirmation-dialog-what-changes-what-s-affected" aria-label="Permalink to &quot;The confirmation dialog: what changes, what&#39;s affected&quot;">​</a></h2><p>The first time you pick a level (or flip one of the toggles below), DevGo explains three things before anything changes. Only &quot;Confirm&quot; applies it:</p><p><strong>① What DevGo actually does</strong> (for &quot;Hide real IP&quot;): changes the browser&#39;s WebRTC settings — disallowing UDP connections that bypass the proxy — so pages&#39; audio/video connections must go through the proxy and sites can&#39;t get your real IP. Applies to all pages.</p><p><strong>② Features that may be affected</strong>:</p><ul><li>In-browser video meetings and voice calls (Tencent Meeting / Feishu / Google Meet web, etc.) may slow down, stutter, or fail — more so if the proxy doesn&#39;t support UDP</li><li>In-page P2P file transfer, live-stream chat, and real-time connections in some web games</li><li>With no proxy on, some in-page calls may also fail to connect</li></ul><p>The dialog also states: <strong>regular browsing, watching videos, downloads, and client apps on your computer (like meeting clients) are unaffected</strong>.</p><p><strong>③ How to recover</strong>: if a web meeting won&#39;t connect, set the level back to &quot;Off&quot; to restore. The popup&#39;s Network page shows whether protection is on.</p><p>The other levels and toggles work the same way: &quot;Disable in-page audio/video calls&quot; lists that all web meetings, voice calls, and screen sharing stop working; &quot;Hide camera and microphone&quot; lists that in-page recording, photo upload, voice input, and identity verification stop working — each dialog ends with its matching recovery step.</p><img src="'+t+'" alt="The confirmation dialog shown before enabling &#39;Hide real IP (recommended)&#39;: actual changes, affected web meetings and voice calls, and how to recover; &#39;Confirm&#39; is the only way to apply"><p><em>The confirmation dialog before enabling &quot;Hide real IP (recommended)&quot; — what actually changes, which features may be affected, and how to recover. (Screenshot shows the Chinese UI; an English version is pending.)</em></p><h2 id="stricter-blocking" tabindex="-1">Stricter blocking <a class="header-anchor" href="#stricter-blocking" aria-label="Permalink to &quot;Stricter blocking&quot;">​</a></h2><p>Beyond levels, two independent toggles no site can get around — at the cost of those features outright. Refresh pages after changing:</p><ul><li><strong>Disable in-page audio/video calls (WebRTC)</strong>: removes WebRTC interfaces before pages load; sites can&#39;t get any of your IPs. All in-browser meetings, calls, and P2P file transfer stop working</li><li><strong>Hide camera and microphone</strong>: blocks the media-device interfaces; sites can&#39;t see which devices you have (often used to identify and track your computer) or use them</li></ul><h2 id="run-a-check" tabindex="-1">Run a check <a class="header-anchor" href="#run-a-check" aria-label="Permalink to &quot;Run a check&quot;">​</a></h2><p>Built into the settings page: click &quot;Start check&quot; and a page you have open probes what a site can actually get —</p><ul><li><strong>Public IP</strong>: with a proxy on, this should be the proxy&#39;s IP — your real IP here means protection isn&#39;t working</li><li><strong>LAN address</strong>: your internal address, best kept hidden</li><li><strong>Local address (anonymized by the browser; safe)</strong>: the browser already mDNS-anonymizes this</li></ul><p>Re-run after changing settings to compare.</p><h2 id="permissions-and-control-status" tabindex="-1">Permissions and control status <a class="header-anchor" href="#permissions-and-control-status" aria-label="Permalink to &quot;Permissions and control status&quot;">​</a></h2><ul><li>The first time you enable protection, the browser asks for the &quot;<strong>Change privacy settings</strong>&quot; permission (<code>privacy</code> is optional and only requested when you enable). If it was denied and protection says &quot;Not granted yet&quot;, picking the level again re-requests it</li><li>The status line shows what the browser is actually using; &quot;controlled by another extension&quot; (another WebRTC extension, say) or locked by policy means DevGo&#39;s settings won&#39;t apply until that&#39;s resolved</li></ul><h2 id="in-the-popup" tabindex="-1">In the popup <a class="header-anchor" href="#in-the-popup" aria-label="Permalink to &quot;In the popup&quot;">​</a></h2><p>The popup&#39;s Network page always shows whether protection is on; with a proxy on but protection off, an orange warning says sites may still see your real IP and links straight to the settings.</p><img src="'+o+'" alt="Network settings: Real IP protection"><p><em>Settings → Network → Real IP protection: protection level, stricter blocking, and the built-in check.</em></p>',32)])])}const b=a(i,[["render",l]]);export{y as __pageData,b as default};
